import { pesquisarAcervo, normalizar } from './provedores/agregador.js';

const $=(s,r=document)=>r.querySelector(s);
const escapar=(v='')=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const linkSeguro=u=>{if(typeof u!=='string'||!u.trim())return'';try{const p=new URL(u,location.origin);return['http:','https:'].includes(p.protocol)?p.href:''}catch{return''}};
const fontesRapidas=['openlibrary','gutenberg','google','wikidata','openalex'];
const stop=new Set('a o e de da do das dos em no na nos nas um uma uns umas para por com sem sobre entre que se seu sua seus suas the of and in on for to from by with an is are book books livro livros edition volume tomo work works'.split(' '));
const estado={nos:[],arestas:[],mapa:new Map(),consulta:'',selecionado:null,expandindo:new Set(),camera:{x:0,y:0,escala:1},arrasto:null,simulando:true,ultimo:performance.now(),quadro:0};
let canvas,ctx,dialogo,detalhe,status,contador,form,campo;

function termos(v){return[...new Set(normalizar(v||'').split(/[^a-z0-9à-ÿ]+/i).map(x=>x.trim()).filter(x=>x.length>2&&!stop.has(x)))].slice(0,18)}
function intersecao(a,b){const A=new Set(a),B=new Set(b);let c=0;for(const x of A)if(B.has(x))c++;return c/Math.max(1,new Set([...A,...B]).size)}
function sementes(l){return termos([l.titulo,...(l.autores||[]),...(l.idiomas||[])].join(' '))}
function corDo(no){if(no.raiz)return'#e8d7a1';const p=normalizar(no.provedor||'');if(p.includes('open library'))return'#b7d0ba';if(p.includes('gutenberg'))return'#e1c3a3';if(p.includes('google'))return'#d7c2a7';if(p.includes('openalex'))return'#a9c9c1';return'#c9c6b6'}
function criarDialogo(){if($('#constelacao'))return;const botao=document.createElement('button');botao.id='abrir-constelacao';botao.innerHTML='<span>↳</span>Constelação';const referencia=$('#abrir-idiomas');referencia?.before(botao);dialogo=document.createElement('dialog');dialogo.id='constelacao';dialogo.className='busca-modal constelacao-modal';dialogo.setAttribute('aria-labelledby','titulo-constelacao');dialogo.innerHTML=`<div class="cabecalho-modal"><a href="#inicio" class="marca-pequena" data-fechar-constelacao>BIBLIOTECA LIVRE · CONSTELAÇÃO</a><button class="fechar" data-fechar-constelacao aria-label="Fechar constelação">×</button></div><div class="constelacao-corpo"><div class="constelacao-topo"><div><p class="rotulo">MAPA NAVEGÁVEL DE RELAÇÕES ENTRE OBRAS</p><h2 id="titulo-constelacao">Constelação de <em>Livros.</em></h2><p>Pesquise uma ideia, autor ou obra. Cada ponto é um livro real encontrado no acervo. A distância muda conforme as relações detectadas. Clique em uma obra para abrir novos ramos.</p></div><form id="form-constelacao"><label class="sr-only" for="campo-constelacao">Pesquisar na constelação</label><input id="campo-constelacao" type="search" maxlength="160" autocomplete="off" placeholder="Darwin, evolução, Machado de Assis, astronomia…"><button class="primario" type="submit">Mapear <span>↗</span></button></form></div><div class="constelacao-ferramentas"><span id="status-constelacao">Escolha um tema para começar.</span><div><button id="centralizar-constelacao" type="button">Centralizar</button><button id="limpar-constelacao" type="button">Limpar mapa</button></div></div><div class="constelacao-palco"><canvas id="canvas-constelacao" aria-label="Mapa interativo de livros relacionados"></canvas><aside id="detalhe-constelacao" class="detalhe-constelacao"><span class="rotulo">NÓ SELECIONADO</span><h3>Explore o mapa</h3><p>Clique em qualquer ponto para ver a obra e buscar relações a partir dela.</p></aside><div id="contador-constelacao" class="contador-constelacao">0 obras · 0 relações</div></div></div>`;document.body.append(dialogo);canvas=$('#canvas-constelacao');ctx=canvas.getContext('2d');detalhe=$('#detalhe-constelacao');status=$('#status-constelacao');contador=$('#contador-constelacao');form=$('#form-constelacao');campo=$('#campo-constelacao');botao.addEventListener('click',abrir);dialogo.querySelectorAll('[data-fechar-constelacao]').forEach(x=>x.addEventListener('click',()=>dialogo.close()));dialogo.addEventListener('click',e=>{if(e.target===dialogo)dialogo.close()});form.addEventListener('submit',e=>{e.preventDefault();buscarRaiz(campo.value)});$('#centralizar-constelacao').addEventListener('click',centralizar);$('#limpar-constelacao').addEventListener('click',limpar);prepararInteracao();new ResizeObserver(redimensionar).observe(canvas);redimensionar();animar()}
function abrir(){if(!dialogo)criarDialogo();if(!dialogo.open)dialogo.showModal();setTimeout(()=>campo.focus(),40)}
function limpar(){estado.nos=[];estado.arestas=[];estado.mapa.clear();estado.selecionado=null;estado.consulta='';estado.camera={x:0,y:0,escala:1};estado.simulando=true;status.textContent='Escolha um tema para começar.';contador.textContent='0 obras · 0 relações';detalhe.innerHTML='<span class="rotulo">NÓ SELECIONADO</span><h3>Explore o mapa</h3><p>Clique em qualquer ponto para ver a obra e buscar relações a partir dela.</p>'}
function centralizar(){if(!estado.nos.length)return;const xs=estado.nos.map(n=>n.x),ys=estado.nos.map(n=>n.y),cx=(Math.min(...xs)+Math.max(...xs))/2,cy=(Math.min(...ys)+Math.max(...ys))/2;estado.camera.x=-cx;estado.camera.y=-cy;estado.camera.escala=1;estado.simulando=true}
function adicionarNo(d,pai=null,raiz=false){const id=raiz?`raiz:${normalizar(d.titulo)}`:String(d.id||`${d.titulo}:${(d.autores||[]).join('|')}`);if(estado.mapa.has(id))return estado.mapa.get(id);const ang=Math.random()*Math.PI*2,dist=pai?110+Math.random()*90:40*Math.random();const no={id,titulo:d.titulo||'Sem título',autores:d.autores||[],provedor:d.provedor||'Biblioteca Livre',ler:linkSeguro(d.ler),capa:linkSeguro(d.capa),idiomas:d.idiomas||[],acessoLivre:Boolean(d.acessoLivre),palavras:sementes(d),x:(pai?.x||0)+Math.cos(ang)*dist,y:(pai?.y||0)+Math.sin(ang)*dist,vx:0,vy:0,raiz,expandido:false,r:raiz?13:7+Math.min(5,(d.relevancia||0)/20)};estado.nos.push(no);estado.mapa.set(id,no);return no}
function ligar(a,b,peso=1){if(!a||!b||a===b)return;if(estado.arestas.some(e=>(e.a===a&&e.b===b)||(e.a===b&&e.b===a)))return;estado.arestas.push({a,b,peso})}
function conectarRelacoes(novos){for(let i=0;i<novos.length;i++)for(let j=i+1;j<novos.length;j++){const a=novos[i],b=novos[j],s=intersecao(a.palavras,b.palavras)+(a.autores[0]&&a.autores[0]===b.autores[0]?0.55:0);if(s>.28)ligar(a,b,Math.min(1.8,.6+s))}}
async function buscarRaiz(q){q=String(q||'').trim();if(!q)return;limpar();estado.consulta=q;campo.value=q;status.textContent=`Mapeando “${q}” em ${fontesRapidas.length} acervos…`;const raiz=adicionarNo({titulo:q,autores:[],provedor:'Consulta',idiomas:[]},null,true);estado.selecionado=raiz;mostrarDetalhe(raiz);try{const resposta=await pesquisarAcervo(q,{pagina:1,fontesAtivas:fontesRapidas,aoFonte:i=>{status.textContent=`${i.concluidas}/${i.total} fontes · ${estado.nos.length-1} obras conectadas`}});const livros=(resposta.livros||[]).slice(0,24),novos=[];for(const l of livros){const n=adicionarNo(l,raiz);ligar(raiz,n,.8);novos.push(n)}conectarRelacoes(novos);raiz.expandido=true;estado.simulando=true;status.textContent=livros.length?`${livros.length} obras formaram a primeira constelação. Clique em um ponto para expandir.`:'Nenhuma obra apareceu nesta consulta. Tente outro termo.';atualizarContador();centralizar()}catch{status.textContent='As fontes não responderam nesta tentativa. Tente novamente.'}}
async function expandir(no){if(!no||no.raiz||no.expandido||estado.expandindo.has(no.id))return;estado.expandindo.add(no.id);status.textContent=`Abrindo novos ramos a partir de “${no.titulo}”…`;const q=[no.titulo,no.autores[0]].filter(Boolean).join(' ');try{const resposta=await pesquisarAcervo(q,{pagina:1,fontesAtivas:fontesRapidas});const novos=[];for(const l of (resposta.livros||[]).slice(0,12)){const n=adicionarNo(l,no);if(n!==no){ligar(no,n,.95);novos.push(n)}}conectarRelacoes(novos);no.expandido=true;estado.simulando=true;status.textContent=`${novos.length} novos caminhos abertos a partir de “${no.titulo}”.`;atualizarContador()}catch{status.textContent='Não foi possível expandir esta obra agora.'}finally{estado.expandindo.delete(no.id)}}
function atualizarContador(){contador.textContent=`${Math.max(0,estado.nos.length-1)} obras · ${estado.arestas.length} relações`}
function mostrarDetalhe(no){estado.selecionado=no;if(!no)return;if(no.raiz){detalhe.innerHTML=`<span class="rotulo">CENTRO DA CONSTELAÇÃO</span><h3>${escapar(no.titulo)}</h3><p>As obras ao redor foram encontradas a partir desta ideia. Linhas adicionais indicam semelhanças de autoria e termos.</p>`;return}const url=no.ler;detalhe.innerHTML=`<span class="rotulo">OBRA CONECTADA</span><h3>${escapar(no.titulo)}</h3><p>${escapar(no.autores.join(' · ')||'Autoria informada pela fonte')}</p><div class="constelacao-meta"><span>${escapar(no.provedor)}</span>${no.idiomas.length?`<span>${escapar(no.idiomas.join(' / '))}</span>`:''}<span>${no.acessoLivre?'Acesso livre':'Catálogo / referência'}</span></div><div class="constelacao-acoes">${url?`<a href="${escapar(url)}" target="_blank" rel="noopener noreferrer">Abrir obra ↗</a>`:''}<button type="button" id="expandir-no" ${no.expandido?'disabled':''}>${no.expandido?'Ramo já expandido':'Expandir relações'}</button></div>`;$('#expandir-no')?.addEventListener('click',()=>expandir(no))}
function redimensionar(){if(!canvas)return;const r=canvas.getBoundingClientRect(),dpr=Math.min(2,devicePixelRatio||1);canvas.width=Math.max(1,Math.round(r.width*dpr));canvas.height=Math.max(1,Math.round(r.height*dpr));ctx.setTransform(dpr,0,0,dpr,0,0)}
function telaParaMundo(x,y){const r=canvas.getBoundingClientRect();return{x:(x-r.left-r.width/2)/estado.camera.escala-estado.camera.x,y:(y-r.top-r.height/2)/estado.camera.escala-estado.camera.y}}
function noEm(x,y){const p=telaParaMundo(x,y);let melhor=null,dist=Infinity;for(const n of estado.nos){const d=Math.hypot(p.x-n.x,p.y-n.y);if(d<n.r+10&&d<dist){melhor=n;dist=d}}return melhor}
function prepararInteracao(){let moveu=false;canvas.addEventListener('pointerdown',e=>{canvas.setPointerCapture(e.pointerId);const n=noEm(e.clientX,e.clientY);estado.arrasto={x:e.clientX,y:e.clientY,cx:estado.camera.x,cy:estado.camera.y,no,ox:n?.x,oy:n?.y};moveu=false});canvas.addEventListener('pointermove',e=>{const a=estado.arrasto;if(!a)return;const dx=e.clientX-a.x,dy=e.clientY-a.y;if(Math.abs(dx)+Math.abs(dy)>4)moveu=true;if(a.no){a.no.x=a.ox+dx/estado.camera.escala;a.no.y=a.oy+dy/estado.camera.escala;a.no.vx=a.no.vy=0;estado.simulando=true}else{estado.camera.x=a.cx+dx/estado.camera.escala;estado.camera.y=a.cy+dy/estado.camera.escala}});canvas.addEventListener('pointerup',e=>{estado.arrasto=null;if(!moveu){const n=noEm(e.clientX,e.clientY);if(n){mostrarDetalhe(n);expandir(n)}}});canvas.addEventListener('wheel',e=>{e.preventDefault();const antes=telaParaMundo(e.clientX,e.clientY),f=e.deltaY<0?1.12:.89;estado.camera.escala=Math.max(.35,Math.min(2.8,estado.camera.escala*f));const depois=telaParaMundo(e.clientX,e.clientY);estado.camera.x+=depois.x-antes.x;estado.camera.y+=depois.y-antes.y},{passive:false})}
function simular(dt){if(!estado.simulando||estado.nos.length<2)return;const nos=estado.nos,forca=Math.min(1,dt/16.67);for(let i=0;i<nos.length;i++){const a=nos[i];for(let j=i+1;j<nos.length;j++){const b=nos[j],dx=b.x-a.x,dy=b.y-a.y,d2=Math.max(90,dx*dx+dy*dy),d=Math.sqrt(d2),f=680/d2;a.vx-=dx/d*f*forca;a.vy-=dy/d*f*forca;b.vx+=dx/d*f*forca;b.vy+=dy/d*f*forca}}for(const e of estado.arestas){const dx=e.b.x-e.a.x,dy=e.b.y-e.a.y,d=Math.max(1,Math.hypot(dx,dy)),alvo=e.a.raiz?155:115,f=(d-alvo)*.0018*e.peso*forca;e.a.vx+=dx/d*f;e.a.vy+=dy/d*f;e.b.vx-=dx/d*f;e.b.vy-=dy/d*f}let energia=0;for(const n of nos){if(n.raiz){n.x*=.94;n.y*=.94}n.vx*=.88;n.vy*=.88;n.x+=n.vx*forca;n.y+=n.vy*forca;energia+=Math.abs(n.vx)+Math.abs(n.vy)}if(energia<.04*nos.length)estado.simulando=false}
function desenhar(){if(!ctx||!canvas)return;const r=canvas.getBoundingClientRect(),w=r.width,h=r.height;ctx.clearRect(0,0,w,h);ctx.save();ctx.translate(w/2,h/2);ctx.scale(estado.camera.escala,estado.camera.escala);ctx.translate(estado.camera.x,estado.camera.y);ctx.lineWidth=1/estado.camera.escala;for(const e of estado.arestas){const alfa=.12+.18*Math.min(1,e.peso);ctx.strokeStyle=`rgba(224,211,176,${alfa})`;ctx.beginPath();ctx.moveTo(e.a.x,e.a.y);ctx.lineTo(e.b.x,e.b.y);ctx.stroke()}for(const n of estado.nos){const selecionado=n===estado.selecionado;ctx.beginPath();ctx.fillStyle=corDo(n);ctx.shadowColor=selecionado?'rgba(232,215,161,.75)':'rgba(232,215,161,.18)';ctx.shadowBlur=(selecionado?22:8)/estado.camera.escala;ctx.arc(n.x,n.y,n.r+(selecionado?2:0),0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;if(n.raiz||selecionado||estado.camera.escala>1.15){ctx.font=`${n.raiz?'600 ':'400 '}${Math.max(9,11/estado.camera.escala)}px ui-sans-serif,system-ui`;ctx.fillStyle='rgba(244,239,222,.88)';ctx.textAlign='center';ctx.textBaseline='top';const texto=n.titulo.length>38?n.titulo.slice(0,36)+'…':n.titulo;ctx.fillText(texto,n.x,n.y+n.r+7,180)}}ctx.restore()}
function animar(t=performance.now()){const dt=Math.min(32,t-estado.ultimo);estado.ultimo=t;simular(dt);desenhar();estado.quadro=requestAnimationFrame(animar)}

criarDialogo();
window.BibliotecaConstelacao={abrir,buscar:buscarRaiz};
